class NPCToon:

    def __init__(self, zoneId, name, head, torso, legs, eyelashes,
                 armColor, legColor, headColor, gloveColor, eyeColor, earColor=None,
                 shirtColor: tuple[float, float, float, float] = (1, 1, 1),
                 sleeveColor: tuple[float, float, float, float] = (1, 1, 1),
                 shortsColor: tuple[float, float, float, float] = (1, 1, 1),
                 equippedItems: tuple = None, npcType: NPCToonEnum = NPCToonEnum.REGULAR, tag: str | None = None,
                 pos: tuple[float, float, float, float] | None = None,
                 holidayIds: tuple[int] = None, nameWordwrap: float | None = None):
        if equippedItems is None:
            equippedItems = []
        if holidayIds is None:
            holidayIds = None
        self.zoneId = zoneId
        self.name = name
        self.head = head
        self.torso = torso
        self.legs = legs
        self.eyelashes = eyelashes
        self.armColor = armColor
        self.legColor = legColor
        self.headColor = headColor
        self.gloveColor = gloveColor
        self.eyeColor = eyeColor
        self.earColor = earColor if earColor else headColor
        self.shirtColor = shirtColor
        self.sleeveColor = sleeveColor
        self.shortsColor = shortsColor
        self.equippedItems = equippedItems
        self.npcType = npcType
        self.tag = tag
        self.pos = pos
        self.holidayIds = holidayIds
        self.nameWordwrap = nameWordwrap

    def __str__(self) -> str:
        return f"NPCToon - {self.name} (Zone: {self.zoneId})"



    def getToonDNA(self) -> ToonDNA.ToonDNA:
        dna = ToonDNA.ToonDNA()
        dna.newToonFromProperties(self.head, self.torso, self.legs, 'f', self.armColor, self.gloveColor,
                                  self.legColor, self.headColor, 0, 0, 0, 0, 0, 0)
        return dna

    def createNPC(self, npc, pos_index):
        npc.setName(self.name)
        npc.setDNAString(self.getToonDNA().makeNetString())
        npc.setHp(15)
        npc.setMaxHp(15)
        npc.setPositionIndex(pos_index)
        npc.setCanSpawn(self.canSpawn())
        npc.npcType = self.tag or ''
        npc.generateWithRequired(self.zoneId)

        # Configure inventory items
        inventoryItems: list[InventoryItem] = [InventoryItem.fromSubtype(subtype) for subtype in self.equippedItems]
        for item in inventoryItems:
            if item.getItemType() == ItemType.Cosmetic_Clothing_Top:
                item.setAttribute(ItemAttribute.CLOTHES_PRIMARY_COL, self.shirtColor)
                item.setAttribute(ItemAttribute.CLOTHES_SECONDARY_COL, self.sleeveColor)
            elif item.getItemType() == ItemType.Cosmetic_Clothing_Bottom:
                item.setAttribute(ItemAttribute.CLOTHES_PRIMARY_COL, self.shortsColor)
        npc.b_setEquippedItems(inventoryItems)

        if hasattr(npc, 'startAnimState'):
            npc.d_setAnimState(npc.startAnimState, 1.0)
        else:
            npc.d_setAnimState('neutral', 1.0)
        return npc

    def createNPCLocal(self, toonClass=None, extraArgs=None, extraCallables=None):
        from toontown.toon import Toon
        from toontown.inventory.base.InventoryItem import InventoryItem
        from toontown.inventory.enums.ItemEnums import ItemType
        from toontown.inventory.enums.ItemAttribute import ItemAttribute
        if extraArgs is None:
            extraArgs = []
        if extraCallables is None:
            extraCallables = []
        if toonClass is None:
            npc = Toon.Toon()
        else:
            npc = toonClass(*extraArgs)
            for f in extraCallables:
                f(npc)
        npc.setName(self.name)
        npc.setPickable(0)
        npc.setPlayerType(NametagGroup.CCNoChat)
        npc.addActive()
        npc.setDNAString(self.getToonDNA().makeNetString())

        # Apply the NPC's equipped clothing items (same as distributed createNPC),
        # so local/cutscene NPCs get their designed outfit instead of default DNA clothes.
        inventoryItems = [InventoryItem.fromSubtype(subtype) for subtype in self.equippedItems]
        for item in inventoryItems:
            if item.getItemType() == ItemType.Cosmetic_Clothing_Top:
                item.setAttribute(ItemAttribute.CLOTHES_PRIMARY_COL, self.shirtColor)
                item.setAttribute(ItemAttribute.CLOTHES_SECONDARY_COL, self.sleeveColor)
            elif item.getItemType() == ItemType.Cosmetic_Clothing_Bottom:
                item.setAttribute(ItemAttribute.CLOTHES_PRIMARY_COL, self.shortsColor)
        npc.setToonEquippedItems(inventoryItems)

        if self.tag:
            npc.npcType = self.tag
            npc.setToonTag(npc.npcType)
        if self.nameWordwrap:
            npc.nametag.setNameWordwrap(self.nameWordwrap)
        npc.request('neutral')
        npc.setNPC(True)
        return npc

    def canSpawn(self):
        """
        Returns a bool for whether this NPC can spawn (currently due to holiday restrictions)

        :return: True if no holiday restriction OR holiday is running, False otherwise
        """
        if self.holidayIds is None or not len(self.holidayIds):
            return True

        from toontown.ai.HolidayGlobals import HOLIDAY2RANGE
        # Note: we get HOLIDAY2RANGE in the event we create an NPC that could spawn in an oncely holiday
        for holidayId in self.holidayIds:
            if holidayId in HOLIDAY2RANGE:
                holidayRange = HOLIDAY2RANGE[holidayId]
                start = holidayRange.startDatetime
                end = holidayRange.endDatetime
                now = holidayRange.nowDatetime
                # if the holiday is both active and our current time is within the holiday, return True
                if holidayRange.active and start < now < end:
                    return True

        # Might as well do a dev_holiday check here if not prod
        # Altis does not use RealmGlobals so we comment it out
        if RealmGlobals.getCurrentRealm().isPrivateRealm():
            from toontown.ai.HolidayGlobals import DEV_HOLIDAYS
            if len(DEV_HOLIDAYS) and any(x in DEV_HOLIDAYS for x in self.holidayIds):
                return True

        # we hath failed all checks, so we are not allowed to spawn!
        return False

    def getNpcId(self):
        return NPCDefinitionToId[self]


